import hashlib
import threading
import unittest

# Choose a small set of widely-available constructors to test.
constructors_to_test = {}
names = ['md5', 'sha1', 'sha256']
for name in names:
    constructors = set()
    # Add the direct constructor if available
    ctor = getattr(hashlib, name, None)
    if callable(ctor):
        constructors.add(ctor)
    # Add a wrapper via hashlib.new
    def make_new(n):
        def c(data=b'', **kwargs):
            return hashlib.new(n, data, **kwargs)
        c.__name__ = f"new_{n}"
        return c
    try:
        constructors.add(make_new(name))
    except Exception:
        pass
    if constructors:
        constructors_to_test[name] = constructors

if not constructors_to_test:
    raise unittest.SkipTest("No hash constructors available to test")

# For each algorithm and constructor, spawn several threads that
# compute the digest of the same data concurrently using separate
# hash objects, and verify all results match a single-threaded result.
num_threads = 5
# Deterministic test data
chunk = (b'0123456789abcdef' * 64)  # 1024 bytes
total_repeats = 10
data = chunk * total_repeats  # ~10 KB per thread

for algorithm, constructors in constructors_to_test.items():
    is_shake = algorithm.startswith('shake_')  # unused here; kept for intent
    for constructor in constructors:
        # Compute expected digest single-threaded
        try:
            single = constructor(data)
            # For non-shake algorithms, use hexdigest()
            expected = single.hexdigest()
        except TypeError:
            # Some constructors might not accept initial data parameter
            # Try creating empty and updating
            try:
                single = constructor()
                single.update(data)
                expected = single.hexdigest()
            except Exception as exc:
                raise unittest.SkipTest(f"Constructor {constructor!r} cannot hash data in this environment: {exc}")

        results = [None] * num_threads
        threads = []

        def worker(idx):
            try:
                h = constructor(data)
            except TypeError:
                h = constructor()
                h.update(data)
            results[idx] = h.hexdigest()

        for i in range(num_threads):
            t = threading.Thread(target=worker, args=(i,))
            threads.append(t)
            t.start()
        for t in threads:
            t.join()

        # Ensure all thread results were set and match expected
        for i, res in enumerate(results):
            assert res is not None, f"Thread {i} did not produce a result"
            assert res == expected, f"Thread {i} digest != expected for {algorithm} using {constructor}"

