            cflag = True
            numstr = tok[:-1].strip()
        else:
            cflag = False
            numstr = tok
        try:
            pos = int(numstr)
        except Exception:
            raise ValueError(f"Invalid keyword spec '{spec}': position is not an integer")
        if pos <= 0:
            raise ValueError(f"Invalid keyword spec '{spec}': argument positions must be strictly positive")
        if pos in used_positions:
            raise ValueError(f"Invalid keyword spec '{spec}': duplicate positions")
        used_positions.add(pos)
        index = pos - 1
        if cflag:
            if 'msgctxt' in mapping:
                raise ValueError(f"Invalid keyword spec '{spec}': msgctxt can only appear once")
            mapping['msgctxt'] = index
        else:
            if 'msgid' not in mapping:
                mapping['msgid'] = index
            elif 'msgid_plural' not in mapping:
                mapping['msgid_plural'] = index
            else:
                raise ValueError(f"Invalid keyword spec '{spec}': too many positions")
    if 'msgid' not in mapping:
        if 'msgctxt' in mapping:
            raise ValueError(f"Invalid keyword spec '{spec}': msgctxt cannot appear without msgid")
