    pos_map = {}
    for key, val in mapping.items():
        pos = val + 1
        token = str(pos)
        if key == 'msgctxt':
            token += 'c'
        pos_map[pos] = token
    tokens = [pos_map[p] for p in sorted(pos_map)]
    return f"{name}:" + ",".join(tokens)
