            # Tell child to exit and wait for it.
            try:
                os.write(fin_w, b"!")
            except Exception:
                pass
            try:
                os.waitpid(pid, 0)
            except Exception:
                pass

    finally:
        # Clean up any file descriptors that may still be open.
        for fd in (r, w, fin_r, fin_w):
            if fd is None:
                continue
            try:
                os.close(fd)
            except Exception:
