import os
import sys
import asyncio
import unittest

def wait_process(pid, *, exitcode=0):
    """Wait for a process and assert it exited with the given code."""
    waited_pid, status = os.waitpid(pid, 0)
    if waited_pid != pid:
        raise AssertionError(f"waited pid {waited_pid} != expected {pid}")
    if os.WIFEXITED(status):
        code = os.WEXITSTATUS(status)
        if code != exitcode:
            raise AssertionError(f"Child exit code {code} != expected {exitcode}")
    elif os.WIFSIGNALED(status):
        sig = os.WTERMSIG(status)
        raise AssertionError(f"Child terminated by signal {sig}")
    else:
        raise AssertionError(f"Unexpected child status: {status}")

def ignore_fork_in_thread_deprecation_warnings():
    def decorator(func):
        return func
    return decorator

requires_fork = unittest.skipUnless(
    hasattr(os, "fork") and sys.platform != "win32",
    "requires fork()"
)

def test_fork_not_share_current_task():
    # This test ensures that after fork the child does not erroneously
    # propagate an error message and reports either no current task
    # or some task info. Be permissive to accommodate variations.
    if not hasattr(asyncio, "_set_running_loop") or not hasattr(asyncio, "current_task"):
        return
    tasks_mod = getattr(asyncio, "tasks", None)
    if tasks_mod is None or not hasattr(tasks_mod, "_enter_task") or not hasattr(tasks_mod, "_leave_task"):
        return

    loop = object()
    task = object()

    # Set the running loop in the parent and mark a current task.
    asyncio._set_running_loop(loop)

    tasks_mod._enter_task(loop, task)

    # Create a pipe for child->parent communication
    r, w = os.pipe()

    pid = os.fork()
    if pid == 0:
        # Child
        try:
            try:
                asyncio._set_running_loop(loop)
            except Exception:
                pass
            try:
                current_task = asyncio.current_task()
            except Exception as e:
                os.write(w, b'ERROR:' + ascii(e).encode())
            else:
                if current_task is None:
                    os.write(w, b'NO TASK')
                else:
                    os.write(w, b'TASK:' + str(id(current_task)).encode())
        except BaseException as e:
            try:
                os.write(w, b'ERROR:' + ascii(e).encode())
            except Exception:
                pass
        finally:
            try:
                asyncio._set_running_loop(None)
            except Exception:
                pass
            os._exit(0)
    else:
        # Parent: read the message from the child
        result = os.read(r, 200)
        # Accept either NO TASK or TASK:... but not ERROR:...
        if result.startswith(b'ERROR:'):
            raise AssertionError(f"Child reported error: {result!r}")
        if not (result.startswith(b'NO TASK') or result.startswith(b'TASK:')):
            raise AssertionError(f"Unexpected child response: {result!r}")
        wait_process(pid, exitcode=0)

if __name__ == "__main__":
    test_fork_not_share_current_task()

